+
+class NewPasswordFormView extends StatelessWidget {
+  final GlobalKey<FormState> formKey;
+
+  final Rx<bool> obscureNewPassword;
+  final TextEditingController newPasswordController;
+
+  final Rx<bool> obscureConfirmNewPassword;
+  final TextEditingController confirmNewPasswordController;
+
+  final void Function() onPressedSave;
+
+  const NewPasswordFormView({
+    super.key,
+    required this.formKey,
+    required this.newPasswordController,
+    required this.confirmNewPasswordController,
+    required this.obscureNewPassword,
+    required this.obscureConfirmNewPassword,
+    required this.onPressedSave,
+  });
+
+  @override
+  Widget build(BuildContext context) {
+    return Form(
+      key: formKey,
+      child: Column(
+        spacing: AppDimens.padding30,
+        children: [
+          Column(
+            spacing: AppDimens.paddingXL,
+            children: [
+              Obx(() {
+                return NotoTextInputField(
+                  semanticId: NewPasswordKeyId.tfNewPassword,
+                  semanticValue: newPasswordController.text,
+                  controller: newPasswordController,
+                  obscureText: obscureNewPassword.value,
+                  showRequiredLabel: true,
+                  label: Language.labelNewPassword.tr,
+                  suffixIcon: InkWell(
+                    child: obscureNewPassword.value
+                        ? const ImageIcon(
+                            AssetImage(AppIcons.icClosedEye),
+                            color: AppColors.border,
+                          )
+                              : const ImageIcon(
+                            AssetImage(AppIcons.icEyeFilled),
+                            color: AppColors.border,
+                          ),
+                    onTap: () {
+                      obscureNewPassword.toggle();
+                    },
+                  ),
+                  validator: (value) {
+                    return Validator(value)
+                        .isRequired(message: Language.errorPasswordRequired.tr)
+                        .isPasswordValid()
+                        .validate();
+                  },
+                  helperText: Language.helperMinimumCharacter.trParams({
+                    ParamKey.length: "8",
+                  }),
+                );
+              }),
+              Obx(() {
+                return NotoTextInputField(
+                  semanticId: NewPasswordKeyId.tfNewPassword,
+                  semanticValue: confirmNewPasswordController.text,
+                  controller: confirmNewPasswordController,
+                  obscureText: obscureConfirmNewPassword.value,
+                  showRequiredLabel: true,
+                  label: Language.labelConfirmNewPassword.tr,
+                  helperText: Language.helperMustBeSameWithNewPassword.tr,
+                  validator: (value) {
+                    return Validator(value)
+                        .isRequired(message: Language.errorPasswordRequired.tr)
+                        .validConfirmPassword(
+                          newPasswordController.text,
+                          value,
+                        )
+                        .validate();
+                  },
+                  suffixIcon: InkWell(
+                    child: obscureConfirmNewPassword.value
+                        ? const ImageIcon(
+                            AssetImage(AppIcons.icClosedEye),
+                            color: AppColors.border,
+                          )
+                        : const ImageIcon(
+                            AssetImage(AppIcons.icEyeFilled),
+                            color: AppColors.border,
+                          ),
+                    onTap: () {
+                      obscureConfirmNewPassword.toggle();
+                    },
+                  ),
+                );
+              }),
+            ],
+          ),
+          PrimaryOoredooButton(
+            semanticId: NewPasswordKeyId.btnSave,
+            text: Language.labelSavePassword.tr,
+            width: double.infinity,
+            height: AppDimens.size48,
+            fontSize: AppDimens.size18,
+            onPressed: onPressedSave,
+          )
+        ],
+      ),
+    );
+  }
+}
