+import 'package:get/get.dart';
+import 'package:ioh_ide_mobile/app/base/base_controller.dart';
+import 'package:ioh_ide_mobile/core/constants/argument_resource.dart';
+import 'package:ioh_ide_mobile/core/utils/data_state.dart';
+import 'package:ioh_ide_mobile/data/repositories/portal/user/user_portal_repository.dart';
+import 'package:ioh_ide_mobile/models/requests/portal/user/set_new_password_request.dart';
+import 'package:ioh_ide_mobile/models/responses/empty/empty_model.dart';
+
+class NewPasswordController extends BaseController {
+  final _userPortalRepository = Get.find<UserPortalRepository>();
+
+  ///
+  /// Data State
+  ///
+  final setNewPasswordState = Rx<DataState<EmptyModel>?>(null);
+
+  final obscureNewPassword = Rx<bool>(true);
+  final obscureConfirmNewPassword = Rx<bool>(true);
+
+  String? token;
+
+  @override
+  void onInit() {
+    setupArguments();
+
+    super.onInit();
+  }
+
+  void setupArguments() {
+    if (Get.arguments is Map) {
+      if (Get.arguments.containsKey(ArgumentResource.token)) {
+        token = Get.arguments[ArgumentResource.token];
+      }
+    }
+  }
+
+  Future<void> setNewPassword({
+    required String password,
+    required String passwordConfirmation,
+  }) async {
+    final request = SetNewPasswordRequest(
+      token: token,
+      password: password,
+      passwordConfirmation: passwordConfirmation,
+    );
+
+    setNewPasswordState.value = DataState.loading();
+    setNewPasswordState.value = await _userPortalRepository.setNewPassword(
+      request: request
+    );
+  }
+}
