+import 'package:ioh_ide_mobile/view/widgets/bottomsheet/platinum/platinum_information_bottom_sheet.dart';
+
+class NewPasswordScreen extends BaseView<NewPasswordController> {
+  final _globalProfileController = Get.find<GlobalProfileController>();
+
+  final formKey = GlobalKey<FormState>();
+  final newPasswordController = TextEditingController();
+  final confirmNewPasswordController = TextEditingController();
+
+  static Map<String, dynamic> arguments({
+    String? token,
+  }) {
+    return {
+      ArgumentResource.token: token,
+    };
+  }
+
+  NewPasswordScreen({super.key});
+
+  @override
+  List<Worker> addObserver() {
+    return [
+      _observeSetNewPasswordState(),
+    ];
+  }
+
+  @override
+  Widget buildPhoneView(BuildContext context) {
+    return Scaffold(
+      backgroundColor: AppColors.border,
+      body: SafeArea(
+        child: CustomScrollView(
+          slivers: [
+            SliverFillRemaining(
+              hasScrollBody: false,
+              child: Container(
+                width: double.infinity,
+                margin: const EdgeInsets.only(top: AppDimens.size100),
+                padding: const EdgeInsets.all(AppDimens.padding30),
+                decoration: BoxDecoration(
+                  color: AppColors.neutral.shade50,
+                  borderRadius: BorderRadius.only(
+                    topLeft: Radius.circular(AppDimens.radius40),
+                    topRight: Radius.circular(AppDimens.radius40),
+                  ),
+                ),
+                child: Column(
+                  spacing: AppDimens.padding30,
+                  children: [
+                    NewPasswordHeaderView(),
+                    NewPasswordFormView(
+                      formKey: formKey,
+                      newPasswordController: newPasswordController,
+                      confirmNewPasswordController: confirmNewPasswordController,
+                      obscureNewPassword: controller.obscureNewPassword,
+                      obscureConfirmNewPassword: controller.obscureConfirmNewPassword,
+                      onPressedSave: () => _onPressedSave(),
+                    ),
+                  ],
+                ),
+              ),
+            ),
+          ],
+        ),
+      ),
+    );
+  }
+
+  @override
+  Widget buildTabletView(BuildContext context) {
+    return buildPhoneView(context);
+  }
+
+  ///
+  /// On Pressed Save Function
+  ///
+  void _onPressedSave() {
+    FocusManager.instance.primaryFocus?.unfocus();
+
+    if (formKey.currentState?.validate() != true) return;
+
+    controller.setNewPassword(
+      password: newPasswordController.text,
+      passwordConfirmation: confirmNewPasswordController.text,
+    );
+  }
+
+  ///
+  /// Observe Set New Password
+  ///
+  Worker _observeSetNewPasswordState() {
+    return ever(controller.setNewPasswordState, (result) {
+      result?.loading(() {
+        showLoading();
+      });
+
+      result?.success((data) {
+        _onSetNewPasswordSuccess();
+      });
+
+      result?.failed((error) {
+        hideLoading();
+      });
+    });
+  }
+
+  void _onSetNewPasswordSuccess() {
+    hideLoading();
+
+    _showSetNewPasswordSuccessBottomSheet();
+  }
+
+  ///
+  /// Success Save Password Bottom Sheet
+  ///
+  void _showSetNewPasswordSuccessBottomSheet() {
+    Get.bottomSheet(
+      PopScope(
+        canPop: false,
+        onPopInvokedWithResult: (didPop, result) {
+          if (!didPop) {
+            // Close bottom sheet and close New Password page
