import 'dart:io';

import 'package:get/get.dart';
import 'package:ioh_ide_mobile/app/app_routes.dart';
import 'package:ioh_ide_mobile/core/constants/analytic_catalog_category.dart';
import 'package:ioh_ide_mobile/core/constants/analytic_source.dart';
import 'package:ioh_ide_mobile/core/constants/deeplink_path.dart';
import 'package:ioh_ide_mobile/core/constants/default_value.dart';
import 'package:ioh_ide_mobile/core/constants/param_key.dart';
import 'package:ioh_ide_mobile/core/enums/page_type.dart';
import 'package:ioh_ide_mobile/core/enums/trend_category.dart';
import 'package:ioh_ide_mobile/core/extensions/stringified_json_extension.dart';
import 'package:ioh_ide_mobile/core/services/firebase/firebase_service.dart';
import 'package:ioh_ide_mobile/core/extensions/uri_extension.dart';
import 'package:ioh_ide_mobile/core/utils/launch_url.dart';
import 'package:ioh_ide_mobile/models/responses/notification/notification_item_model.dart';
import 'package:ioh_ide_mobile/models/responses/product/product_item_model.dart';
import 'package:ioh_ide_mobile/view/features/account/transaction_status/transaction_status_screen.dart';
import 'package:ioh_ide_mobile/view/features/acticle_detail/article_detail_screen.dart';
import 'package:ioh_ide_mobile/view/features/catalog_product/catalog_product_screen.dart';
import 'package:ioh_ide_mobile/view/features/dashboard/dashboard_controller.dart';
import 'package:ioh_ide_mobile/view/features/detail_product/detail_product_screen.dart';
import 'package:ioh_ide_mobile/view/features/insight/location/location_insight_screen.dart';
import 'package:ioh_ide_mobile/view/features/internet_trend/internet_trend_screen.dart';
import 'package:ioh_ide_mobile/view/features/order/order_detail/order_detail_screen.dart';
import 'package:ioh_ide_mobile/view/features/order/waiting_payment/waiting_payment_screen.dart';

class DeeplinkService {
  DeeplinkService._();

  static String? deeplinkTargetMenu;

  static void handleHasMapDeeplink(Map<String, dynamic> data) {
    _routingDeeplink(Uri.parse(data["url"]));
  }

  static void handleStringDeeplink(String data) {
    final path = data.extractFieldValue("url") ?? DefaultValue.empty;
    _routingDeeplink(Uri.parse(path));
  }

  static void handleNotificationModelDeeplink(NotificationItemModel data) {
    if (data.deepLink != null) {
      _routingDeeplink(Uri.parse(data.deepLink!));
    }
  }

  static Future<void> _routingDeeplink(Uri deeplink) async {
    final path = deeplink.path;

    Uri.encodeComponent(deeplink.toString());

    switch (path) {
      case DeeplinkPath.pendingPayment:
      case DeeplinkPath.paymentBeforeExpired:
        final orderId = deeplink.queryParameters[ParamKey.orderUnderscoreId];
        _navigateToWaitingPaymentPage(orderId);
        break;
      case DeeplinkPath.paymentFailed:
        final orderId = deeplink.queryParameters[ParamKey.orderUnderscoreId];
        _navigateToWaitingPaymentPage(orderId, isPaymentFailed: true);
        break;
      case DeeplinkPath.productNew:
      case DeeplinkPath.productStockAlmostOut:
        _navigateToProductList();
        break;
      case DeeplinkPath.productNewPromo:
      case DeeplinkPath.productReminderPromo:
        _navigateToPromoPage();
        break;
      case DeeplinkPath.paymentSuccess:
        _navigateToTransactionStatusPage();
        break;
      case DeeplinkPath.giveFeedback:
      case DeeplinkPath.applicationUpdate:
        final appStoreUrl = deeplink.queryParameters[ParamKey.appStoreUrl];
        final playStoreUrl = deeplink.queryParameters[ParamKey.playStoreUrl];
        final targetUrl = Platform.isAndroid ? playStoreUrl : appStoreUrl;

        if (targetUrl != null) {
          LaunchUrl.external(Uri.decodeFull(targetUrl));
        }

        break;
      case DeeplinkPath.newFeature:
        _newFeatureHandling(deeplink);
        break;
      case DeeplinkPath.articleNew:
      case DeeplinkPath.articleInterest:
        _navigateToArticlePage();
        break;
      case DeeplinkPath.paymentExpired:
      case DeeplinkPath.subscriptionExpireSoon:
        final productCode = deeplink.queryParameters[ParamKey.productCode];

        _navigateToProductDetail(productCode);
        break;
      case DeeplinkPath.articleTrending:
      case DeeplinkPath.articleGuide:
        final articleSlug = deeplink.queryParameters[ParamKey.articleSlug];

        _navigateToArticleDetail(articleSlug);
        break;
      case DeeplinkPath.subscriptionActive:
        final orderId = deeplink.queryParameters[ParamKey.orderUnderscoreId];
        _navigateToOrderDetailPage(orderId);
        break;
      case DeeplinkPath.internetTrend:
        final trendSource = deeplink.queryParameters[ParamKey.trendSource];
        _navigateToInternetTrendPage(trendSource);
        break;
      case DeeplinkPath.customerInsight:
        _navigateToCustomerInsight();
        break;
      case DeeplinkPath.fnBInsight:
        _navigateToFnBInsight();
        break;
      case DeeplinkPath.retailInsight:
        _navigateToRetailInsight();
        break;
      case DeeplinkPath.locationInsight:
        final provinceName = deeplink.decodedQueryParam(ParamKey.provinceName);
        final cityName = deeplink.decodedQueryParam(ParamKey.cityName);

        _navigateToLocationInsight(provinceName, cityName);
        break;
      default:
        break;
    }
  }

  static void _navigateToWaitingPaymentPage(
    String? orderId, {
    bool isPaymentFailed = false,
  }) {
    if (orderId == null) return;

    _closeDialogAndNavigate(() {
      Get.toNamed(
        AppRoute.waitingPayment,
        arguments: WaitingPaymentScreen.arguments(
          orderId: int.tryParse(orderId) ?? 0,
          fromPaymentFailedNotification: isPaymentFailed,
        ),
      );
    });
  }

  static void _navigateToProductList() {
    _closeDialogAndNavigate(() {
      Get.toNamed(
        AppRoute.catalogProduct,
        arguments: CatalogProductScreen.arguments(catalogCategoryId: null),
      );

      /// Send event to firebase analytics
      FirebaseService.instance.sendViewProductListEvent(
        source: AnalyticSource.deeplink,
        listType: AnalyticCatalogCategory.allCategory,
      );
    });
  }

  static void _navigateToPromoPage() {
    // _closeDialogAndNavigate(() => Get.toNamed(AppRoute.promo));
    //
    // /// Send event to firebase analytics
    // FirebaseService.instance.sendViewAllPromoEvent(
    //   source: AnalyticSource.deeplink,
    // );
  }

  static void _navigateToTransactionStatusPage() {
    _closeDialogAndNavigate(() {
      Get.toNamed(
        AppRoute.transactionStatus,
        arguments: TransactionStatusScreen.arguments(
          transactionType: PageType.transactionStatus,
        ),
      );
    });

    /// Send event to firebase analytics
    FirebaseService.instance.sendViewTransactionStatusEvent(
      source: AnalyticSource.deeplink,
    );
  }

  static void _navigateToArticlePage() {
    _closeDialogAndNavigate(() => Get.toNamed(AppRoute.article));

    /// Send event to firebase analytics
    FirebaseService.instance.sendViewArticleListEvent(
      source: AnalyticSource.deeplink,
    );
  }

  static void _navigateToProductDetail(String? productCode) {
    if (productCode == null) return;

    _closeDialogAndNavigate(() {
      Get.toNamed(
        AppRoute.detailProduct,
        preventDuplicates: false,
        arguments: DetailProductScreen.arguments(productCode: productCode),
      );
    });

    /// Send event to firebase analytics
    FirebaseService.instance.sendViewProductDetailEvent(
      source: AnalyticSource.deeplink,
      product: ProductItemModel(id: productCode),
    );
  }

  static void _navigateToArticleDetail(String? slug) {
    if (slug == null) return;

    _closeDialogAndNavigate(() {
      Get.toNamed(
        AppRoute.articleDetail,
        arguments: ArticleDetailScreen.arguments(slug: slug),
      );
    });

    /// Send event to firebase analytics
    FirebaseService.instance.sendViewArticleDetail(
      source: AnalyticSource.deeplink,
      articleName: DefaultValue.empty,
      slug: slug,
      articleTags: DefaultValue.empty,
      articleDate: DefaultValue.empty
    );
  }

  static void _navigateToOrderDetailPage(String? orderId) {
    if (orderId == null) return;

    _closeDialogAndNavigate(() {
      Get.toNamed(
        AppRoute.orderDetail,
        arguments: OrderDetailScreen.arguments(
          orderId: int.tryParse(orderId) ?? 0,
        ),
      );
    });

    /// Send event to firebase analytics
    FirebaseService.instance.sendViewOrderDetailEvent(
      source: AnalyticSource.deeplink,
      orderNumber: orderId,
    );
  }

  static void _newFeatureHandling(Uri deeplink) {
    final menu = deeplink.queryParameters[ParamKey.menu];

    deeplinkTargetMenu = menu;

    if (Get.isRegistered<DashboardController>()) {
      Get.find<DashboardController>().navigateToDeeplinkMenu();
    }
  }

  static void _navigateToInternetTrendPage(String? trendSource) {
    if (trendSource == null) return;

    final trendCategory = TrendCategory.from(trendSource);

    if (trendCategory != null) {
      _closeDialogAndNavigate(() {
        Get.toNamed(
          AppRoute.internetTrend,
          arguments: InternetTrendScreen.arguments(
            trendCategory: trendCategory,
          ),
        );
        /// Send event to firebase analytics
        if (trendCategory == TrendCategory.youtube) {
          FirebaseService.instance.sendViewYoutubeTrendEvent(
              source: AnalyticSource.deeplink
          );
        } else {
          FirebaseService.instance.sendViewGoogleTrendEvent(
              source: AnalyticSource.deeplink
          );
        }
      });
    }
  }

  static void _navigateToCustomerInsight() {
    _closeDialogAndNavigate(() {
      Get.toNamed(AppRoute.customerInsight);
    });

    /// Send event to firebase analytics
    FirebaseService.instance.sendViewInsightPelangganEvent(
      source: AnalyticSource.deeplink,
    );
  }

  static void _navigateToFnBInsight() {
    _closeDialogAndNavigate(() {
      Get.toNamed(AppRoute.fnbInsight);
    });

    /// Send event to firebase analytics
    FirebaseService.instance.sendViewInsightFnbEvent(
      source: AnalyticSource.deeplink,
    );
  }

  static void _navigateToRetailInsight() {
    _closeDialogAndNavigate(() {
      Get.toNamed(AppRoute.retailInsight);
    });

    /// Send event to firebase analytics
    FirebaseService.instance.sendViewInsightRetailEvent(
      source: AnalyticSource.deeplink,
    );
  }

  static void _navigateToLocationInsight(String? province, String? city) {
    _closeDialogAndNavigate(() {
      Get.toNamed(
        AppRoute.locationInsight,
        arguments: LocationInsightScreen.arguments(
          province: province,
          city: city,
        ),
      );
    });

    /// Send event to firebase analytics
    FirebaseService.instance.sendViewInsightLocationEvent(
      source: AnalyticSource.deeplink,
    );
  }

  static void _closeDialogAndNavigate(void Function() navigate) {
    if (Get.isDialogOpen ?? false) {
      Get.back();
    }

    navigate();
  }
}

