    19→
    20→class DashboardController extends BaseController {
    21→  final _appSettingRepository = Get.find<AppSettingsRepository>();
    22→
    23→  final tabSelected = Rx<BottomNavigationType>(BottomNavigationType.home);
    24→
    25→  bool canCloseApp = false;
    26→
    27→  Timer? timer;
    28→
    29→  ///
    30→  /// Data State
    31→  ///
    32→  final showTutorialState = Rx<bool>(false);
    33→
    34→  final isDeviceSave = Rx<bool>(true);
    35→
    36→  ///
    37→  /// Data
    38→  ///
    39→  BuildContext? tutorialContext;
    40→
    41→  final GlobalKey menuKey = GlobalKey();
    42→  final GlobalKey bottomNavigationKey = GlobalKey();
    43→  final GlobalKey btnInfoKey = GlobalKey();
    44→
    45→  final currentTutorialPosition = Rx<int>(0);
    46→
    47→  String source = AnalyticSource.firstAppOpen;
    48→
    49→  @override
    50→  void onReady() {
    51→    // FirebaseService.instance.logAppOpen();
    52→    sendTabViewEvent();
    53→    source = getTabSource();
    54→
    55→    NotificationService.registerDeviceInfo();
    56→
    57→    getData();
    58→    super.onReady();
    59→  }
    60→
    61→  @override
    62→  void onClose() {
    63→    timer?.cancel();
    64→    super.onClose();
    65→  }
    66→
    67→  Future<void> getData() async {
    68→    shouldShowTutorial();
    69→    super.onReady();
    70→  }
    71→
    72→  Future<void> shouldShowTutorial() async {
    73→    showTutorialState.value = await _appSettingRepository.shouldShowTutorial();
    74→  }
    75→
    76→  void startTutorial() async {
    77→    /// Send event to firebase analytics
    78→    final isFirstInstall = showTutorialState.value;
    79→    final userId =
    80→        Get.find<GlobalProfileController>().user.value?.id ?? DefaultValue.dash;
    81→    final isAuthenticated =
    82→        Get.find<GlobalProfileController>().isAuthenticated.value;
    83→
    84→    FirebaseService.instance.sendViewShowcaseEvent(
    85→      loggedIn: isAuthenticated,
    86→      userId: userId,
    87→      firstInstall: isFirstInstall,
    88→    );
    89→
    90→    currentTutorialPosition.value = 0;
    91→    Get.find<HomeController>().mainScrollController.jumpTo(0);
    92→    if (tutorialContext == null) return;
    93→    ShowCaseWidget.of(
    94→      tutorialContext!,
    95→    ).startShowCase([menuKey, bottomNavigationKey, btnInfoKey]);
    96→    await Future.delayed(DelayDuration.delay50);
    97→    currentTutorialPosition.value++;
    98→  }
    99→
   100→  void nextTutorial() async {
   101→    currentTutorialPosition.value++;
   102→  }
   103→
   104→  void previousTutorial() async {
   105→    currentTutorialPosition.value--;
   106→  }
   107→
   108→  Future<void> finishTutorial() async {
   109→    if (tutorialContext == null) return;
   110→
   111→    currentTutorialPosition.value = DefaultValue.zero;
   112→    ShowCaseWidget.of(tutorialContext!).dismiss();
   113→    await _appSettingRepository.setShouldShowTutorial(false);
   114→  }
   115→
   116→  void navigateToDeeplinkMenu() {
   117→    final String? menu = DeeplinkService.deeplinkTargetMenu?.toLowerCase();
   118→
   119→    if (menu != null) {
   120→      switch (MainMenu.from(menu)) {
   121→        case MainMenu.beranda:
   122→        case MainMenu.home:
   123→          tabSelected(BottomNavigationType.home);
   124→          break;
   125→        case MainMenu.toko:
   126→          tabSelected(BottomNavigationType.marketplace);
   127→          break;
   128→        case MainMenu.notification:
   129→        case MainMenu.notifikasi:
   130→          tabSelected(BottomNavigationType.notification);
   131→          break;
   132→        case MainMenu.account:
   133→        case MainMenu.akun:
   134→          tabSelected(BottomNavigationType.account);
   135→          break;
   136→        case MainMenu.academy:
   137→          _navigateToAcademy();
   138→          break;
   139→        case MainMenu.wawasan:
   140→          _navigateToWawasan();
   141→          break;
   142→        default:
   143→      }
   144→    }
   145→  }
   146→
   147→  ///
   148→  /// Firebase Analytics
   149→  ///
   150→  String getTabSource() {
   151→    String source = DefaultValue.dash;
   152→
   153→    if (tabSelected.value == BottomNavigationType.home) {
   154→      source = AnalyticSource.tabHomepage;
   155→    } else if (tabSelected.value == BottomNavigationType.marketplace) {
   156→      source = AnalyticSource.tabToko;
   157→    } else if (tabSelected.value == BottomNavigationType.notification) {
   158→      source = AnalyticSource.tabNotification;
   159→    } else if (tabSelected.value == BottomNavigationType.account) {
   160→      source = AnalyticSource.tabAccount;
   161→    }
   162→
   163→    return source;
   164→  }
   165→
   166→  void sendTabViewEvent() {
   167→    switch (tabSelected.value) {
   168→      case BottomNavigationType.home:
   169→
   170→        /// Send event to firebase analytics
   171→        FirebaseService.instance.sendViewTabHomepageEvent(source: source);
   172→        break;
   173→      case BottomNavigationType.marketplace:
