import 'dart:async';

import 'package:flutter/widgets.dart';
import 'package:get/get.dart';
import 'package:ioh_ide_mobile/app/app_routes.dart';
import 'package:ioh_ide_mobile/app/base/base_controller.dart';
import 'package:ioh_ide_mobile/core/constants/analytic_source.dart';
import 'package:ioh_ide_mobile/core/constants/default_value.dart';
import 'package:ioh_ide_mobile/core/constants/delay_duration.dart';
import 'package:ioh_ide_mobile/core/enums/bottom_navigation_type.dart';
import 'package:ioh_ide_mobile/core/enums/main_menu.dart';
import 'package:ioh_ide_mobile/core/services/deeplink/deeplink_service.dart';
import 'package:ioh_ide_mobile/core/services/firebase/firebase_service.dart';
import 'package:ioh_ide_mobile/core/services/notification/notification_service.dart';
import 'package:ioh_ide_mobile/data/repositories/app_settings/app_settings_repository.dart';
import 'package:ioh_ide_mobile/view/features/home/home_controller.dart';
import 'package:ioh_ide_mobile/view/global_controller/global_profile_controller.dart';
import 'package:showcaseview/showcaseview.dart';

class DashboardController extends BaseController {
  final _appSettingRepository = Get.find<AppSettingsRepository>();

  final tabSelected = Rx<BottomNavigationType>(BottomNavigationType.home);

  bool canCloseApp = false;

  Timer? timer;

  ///
  /// Data State
  ///
  final showTutorialState = Rx<bool>(false);

  final isDeviceSave = Rx<bool>(true);

  ///
  /// Data
  ///
  BuildContext? tutorialContext;

  final GlobalKey menuKey = GlobalKey();
  final GlobalKey bottomNavigationKey = GlobalKey();
  final GlobalKey btnInfoKey = GlobalKey();

  final currentTutorialPosition = Rx<int>(0);

  String source = AnalyticSource.firstAppOpen;

  @override
  void onReady() {
    // FirebaseService.instance.logAppOpen();
    sendTabViewEvent();
    source = getTabSource();

    NotificationService.registerDeviceInfo();

    getData();
    super.onReady();
  }

  @override
  void onClose() {
    timer?.cancel();
    super.onClose();
  }

  Future<void> getData() async {
    shouldShowTutorial();
    super.onReady();
  }

  Future<void> shouldShowTutorial() async {
    showTutorialState.value = await _appSettingRepository.shouldShowTutorial();
  }

  void startTutorial() async {
    /// Send event to firebase analytics
    final isFirstInstall = showTutorialState.value;
    final userId =
        Get.find<GlobalProfileController>().user.value?.id ?? DefaultValue.dash;
    final isAuthenticated =
        Get.find<GlobalProfileController>().isAuthenticated.value;

    FirebaseService.instance.sendViewShowcaseEvent(
      loggedIn: isAuthenticated,
      userId: userId,
      firstInstall: isFirstInstall,
    );

    currentTutorialPosition.value = 0;
    Get.find<HomeController>().mainScrollController.jumpTo(0);
    if (tutorialContext == null) return;
    ShowCaseWidget.of(
      tutorialContext!,
    ).startShowCase([menuKey, bottomNavigationKey, btnInfoKey]);
    await Future.delayed(DelayDuration.delay50);
    currentTutorialPosition.value++;
  }

  void nextTutorial() async {
    currentTutorialPosition.value++;
  }

  void previousTutorial() async {
    currentTutorialPosition.value--;
  }

  Future<void> finishTutorial() async {
    if (tutorialContext == null) return;

    currentTutorialPosition.value = DefaultValue.zero;
    ShowCaseWidget.of(tutorialContext!).dismiss();
    await _appSettingRepository.setShouldShowTutorial(false);
  }

  void navigateToDeeplinkMenu() {
    final String? menu = DeeplinkService.deeplinkTargetMenu?.toLowerCase();

    if (menu != null) {
      switch (MainMenu.from(menu)) {
        case MainMenu.beranda:
        case MainMenu.home:
          tabSelected(BottomNavigationType.home);
          break;
        case MainMenu.toko:
          tabSelected(BottomNavigationType.marketplace);
          break;
        case MainMenu.notification:
        case MainMenu.notifikasi:
          tabSelected(BottomNavigationType.notification);
          break;
        case MainMenu.account:
        case MainMenu.akun:
          tabSelected(BottomNavigationType.account);
          break;
        case MainMenu.academy:
          _navigateToAcademy();
          break;
        case MainMenu.wawasan:
          _navigateToWawasan();
          break;
        default:
      }
    }
  }

  ///
  /// Firebase Analytics
  ///
  String getTabSource() {
    String source = DefaultValue.dash;

    if (tabSelected.value == BottomNavigationType.home) {
      source = AnalyticSource.tabHomepage;
    } else if (tabSelected.value == BottomNavigationType.marketplace) {
      source = AnalyticSource.tabToko;
    } else if (tabSelected.value == BottomNavigationType.notification) {
      source = AnalyticSource.tabNotification;
    } else if (tabSelected.value == BottomNavigationType.account) {
      source = AnalyticSource.tabAccount;
    }

    return source;
  }

  void sendTabViewEvent() {
    switch (tabSelected.value) {
      case BottomNavigationType.home:

        /// Send event to firebase analytics
        FirebaseService.instance.sendViewTabHomepageEvent(source: source);
        break;
      case BottomNavigationType.marketplace:

        /// Send event to firebase analytics
        FirebaseService.instance.sendViewTabTokoEvent(source: source);
        break;
      case BottomNavigationType.notification:

        /// Send event to firebase analytics
        FirebaseService.instance.sendViewTabNotificationEvent(source: source);
        break;
      case BottomNavigationType.account:

        /// Send event to firebase analytics
        FirebaseService.instance.sendViewTabAccountEvent(source: source);
        break;
    }
  }

  ///
  /// Navigation
  ///
  void _navigateToAcademy() {
    Get.toNamed(AppRoute.academy);
  }

  void _navigateToWawasan() {
    Get.toNamed(AppRoute.wawasan);
  }

  void navigateToToko({required String source}) {
    if (tabSelected.value != BottomNavigationType.marketplace) {
      this.source = source;

      tabSelected.value = BottomNavigationType.marketplace;
    }
  }

  void navigateToHome({required String source}) {
    if (tabSelected.value != BottomNavigationType.home) {
      this.source = source;

      tabSelected.value = BottomNavigationType.home;
    }
  }

  void navigateToAccount({required String source}) {
    if (tabSelected.value != BottomNavigationType.account) {
      this.source = source;

      tabSelected.value = BottomNavigationType.account;
    }
  }
}

