switch (path) {
  case DeeplinkPath.pendingPayment:
  // ... other cases
  case DeeplinkPath.firstLogin:
    final token = deeplink.decodedQueryParam(ParamKey.token);
    _navigateToNewPassword(token);
    break;
  default:
    break;
}

static void _navigateToNewPassword(String? token) {
  if (token == null || token.isEmpty) {
    // Log error or show error message
    return;
  }

  if (Get.isRegistered<DashboardController>()) {
    Get.find<DashboardController>().startSetNewPasswordFlow(token: token);
  } else {
    // Navigate directly if DashboardController not registered
    Get.toNamed(AppRoute.newPassword, arguments: {ArgumentResource.token: token});
  }
}
```

**Recommendation:** Add the missing DeeplinkPath.firstLogin case to the switch statement in _routingDeeplink method. Also add proper token validation before navigation and handle the case when DashboardController is not registered.

